(32, 'Custom Field Report', '$this->CensusCustomField->unbindModel(array(''hasMany'' => array(''CensusCustomFieldOption'')));\r\n$this->CensusCustomValue->bindModel(array(\r\n           ''belongsTo''=> array(\r\n                ''SchoolYear'' => array(''foreignKey'' => ''school_year_id''),\r\n            	''CensusCustomFieldOption'' => array(\r\n            		''joinTable''  => ''census_custom_field_options'',\r\n                    ''foreignKey'' => false,\r\n                    ''conditions'' => array('' CensusCustomFieldOption.id = CensusCustomValue.value '')\r\n                ),\r\n            )\r\n));\r\n$data = $this->CensusCustomValue->find(''all'',array(''fields''=>array(''SchoolYear.name AS AcademicYear'',''InstitutionSite.name AS InstitutionName'',''CensusCustomField.name AS Information'',''CensusCustomField.type AS Type'',''CensusCustomValue.value AS Value'',''CensusCustomFieldOption.value AS Option''),{cond}));foreach($data as $key => &$value) { if ($value[''CensusCustomField''][''Type''] != 2 && $value[''CensusCustomField''][''Type''] != 5) { $value[''CensusCustomValue''][''Value''] = $value[''CensusCustomFieldOption''][''Option'']; }}', 'AcademicYear,InstitutionName,Information,Value', 1, 32, NULL, NULL, 1, '0000-00-00 00:00:00'),
(33, 'Custom Table Report', '$this->CensusGridValue->bindModel(array( ''belongsTo''=> array( ''SchoolYear'' => array(''foreignKey'' => ''school_year_id''), ''CensusGrid'', ''CensusGridXCategory'', ''CensusGridYCategory'', ''InstitutionSite''=>array(''foreignKey'' => ''institution_site_id'') ) )); $data = $this->CensusGridValue->find(''all'',array(''fields''=>array(''SchoolYear.name AS AcademicYear'',''InstitutionSite.name AS InstitutionName'',''CensusGridXCategory.name AS GridXCategory'',''CensusGridYCategory.name AS GridYCategory'',''CensusGridValue.value AS Value''),{cond}));', 'AcademicYear,InstitutionName,GridXCategory,GridYCategory,Value', 1, 33, NULL, NULL, 1, '0000-00-00 00:00:00'),
