(52, 'Room Report', '$this->CensusRoom->bindModel(array( ''belongsTo''=> array( ''SchoolYear'' => array(''foreignKey'' => ''school_year_id''), ''InfrastructureStatus'' => array(''foreignKey'' => ''infrastructure_status_id''), ''InstitutionSite''=>array(''foreignKey'' => ''institution_site_id'') ) )); $data = $this->CensusRoom->find(''all'',array(''fields''=>array(''SchoolYear.name AS AcademicYear'',''InstitutionSite.name AS InstitutionName'',''InfrastructureRoom.name AS Room'',''InfrastructureStatus.name AS Status'',''CensusRoom.value AS Value''),{cond}));', 'AcademicYear,InstitutionName,Room,Status,Value', 1, 52, NULL, NULL, 1, '0000-00-00 00:00:00'),
