(153, 'Data Outliers', 'Census Numbers that have age or total of male and female numbers beyond the specified range in settings.', 'csv', 'Data Quality', 'System Data Quality Reports', NULL, NULL, 42, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(154, 'Missing Coordinates', 'List of Institutions with latitude and/or longitude values of 0 or null', 'csv', 'Data Quality', 'System Data Quality Reports', NULL, NULL, 43, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1000, 'Student Report', 'Number of students (enrollment) by sex, age, locality and grade', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 44, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1001, 'Teacher Report', 'Number of teachers by sex, locality and grade', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 45, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1002, 'Staff Report', 'Number of staff by sex and locality', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 46, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1003, 'Institutions Report', 'Number of institutions by provider and sector', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 47, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1004, 'Institution Sites Report', 'Number of institution sites by locality and type', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 48, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1005, 'Population Report', 'Number of people by sex and age', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 49, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1006, 'Net Enrolment Rate Report', 'Divide the number of pupils (or students) enrolled who are of the official age group for a given level of education by the population for the same age group and multiply the result by 100. This indicator has dimension values of sex, locality and grade.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 50, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1007, 'Gross Enrolment Rate Report', 'Divide the number of pupils (or students) enrolled in a given level of education regardless of age by the population of the age group which officially corresponds to the given level of education, and multiply the result by 100. This indicator has dimension values of sex, locality and grade.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 51, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1008, 'Net Intake Rate Report', 'Divide the number of children of official primary school-entrance age who enter the first grade of primary education for the first time by the population of the same age, and multiply the result by 100. This indicator has dimension values of sex and locality.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 52, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1009, 'Gross Intake Rate Report', 'Divide the number of new entrants in grade 1, irrespective of age, by the population of official school-entrance age, and multiply the result by 100. This indicator has dimension values of sex, locality and grade.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 53, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1010, 'Repetition Rate Report', 'Divide the number of repeaters in a given grade in school year t+1 by the number of pupils from the same cohort enrolled in the same grade in the previous school year t . This indicator has dimension values of sex, locality, sector and grade.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 54, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1011, 'Completion Rate Report', 'Divide the number of primary graduates, irrespective of age, by the population of theoretical primary graduation, and multiply the result by 100. This indicator has dimension values of sex, locality and sector.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 55, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1012, 'Survival Rate Report', 'Divide the total number of pupils belonging to a school-cohort who reached each successive grade of the specified level of education by the number of pupils in the school-cohort i.e. those originally enrolled in the first grade of primary education, and multiply the result by 100. The survival rate is calculated on the basis of the reconstructed cohort method, which uses data on enrolment and repeaters for two consecutive years. This indicator has dimension values of sex, locality and sector.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 56, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1013, 'Transition Rate Report', 'Divide the number of new entrants in the first grade of the specified higher cycle or level of education by the number of pupils who were enrolled in the final grade of the preceding cycle or level of education in the previous school year, and multiply by 100. This indicator has dimension values of sex, locality, sector and grade.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 57, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1014, 'Pupil Teacher Ratio Report', 'Divide the total number of pupils enrolled at the specified level of education by the number of teachers at the same level. This indicator has dimension values of locality, sector and level of education.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 58, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1015, 'Pupil Class Ratio Report', 'Divide the total number of pupils enrolled at the specified level of education by the number of classes at the same level. This indicator has dimension values of locality and sector.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 59, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1016, 'Trained Teachers Report', 'Divide the number of teachers of the specified level of education who have received the minimum required teacher training by the total number of teachers at the same level of education, and multiply the result by 100. This indicator has dimension values of locality, sector and level of education.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 60, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1017, 'Gender Parity Index (Students) Report', 'Divide the number of female students by the number of male students. This indicator has dimension values of sex, locality, sector and level of education.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 61, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1018, 'Female Students Report', 'Divide the number of female tertiary students enrolled in a specified ISCED level by the total number of students (male plus female) in that level in a given academic-year, and multiply the result by 100. This indicator has dimension values of locality, sector and level of education.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 62, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1019, 'Female Teachers Report', 'Divide the total number of female teachers at a given level of education by the total number of teachers (male and female) at the same level in a given school year, and multiply by 100. This indicator has dimension values of locality, sector and level of education.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 63, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1020, 'Private Enrolment Report', 'Divide the number of pupils (or students) enrolled in private educational institutions in a given level of education by total enrolment (public and private) at the same level of education, and multiply the result by 100. This indicator has dimension values of sex, locality and level of education.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 64, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1021, 'Pupil Textbook Ratio Report', 'Divide the total number of pupils enrolled at the specified level of education by the number of textbooks at the same level. This indicator has dimension values of locality, and sector.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 65, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1022, 'Water Sources Report', 'Number of water sources by type. This indicator has dimension values of locality, sector and condition.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 66, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1023, 'Sanitation Facilities Report', 'Number of sanitation facilities by type. This indicator has dimension values of locality, sector and condition.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 67, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1024, 'Public Expenditure per Education Level Report', 'Divide total public expenditure for each level of education in a given financial year by the total public expenditure on education for the same financial year and multiply the result by 100. ', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 68, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1025, 'Public Expenditure on Education Report', 'Divide total public expenditure on education incurred by all government agencies/departments in a given financial year by the total government expenditure for the same financial year and multiply by 100.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 69, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1026, 'Public Expenditure on Education by GNP Report', 'Divide total public expenditure on education in a given financial year by the Gross National Product (GNP) or Gross National Income (GNI) of the country for the corresponding year and multiply by 100.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 70, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
(1027, 'Public Expenditure per Pupil Report', 'Divide per pupil public current expenditure on each level of education in a given year by the GNI per capita for the same year and multiply by 100. This indicator has dimension values of level of education.', 'ind', 'Indicator', 'Indicator Reports', 'Indicator,SubGroup,AreaName,TimePeriod,DataValue,Classification', NULL, 71, 1, 1, NULL, NULL, 1, '0000-00-00 00:00:00'),
